import {output,latch} from './logic-core-20261112.js';
const lessons=[
{type:'WIRE',name:'연결',color:'#f34c39',fg:'#fff8eb',title:'연결하면, 켜져요.',rule:'입력 그대로 전달해요',n:1,note:['노란 버튼을 눌러 불빛을 켜보세요.','버튼이 켜지면, 연결된 불빛도 켜져요.']},
{type:'NOT',name:'반대로',color:'#35b4b0',fg:'#142f2e',title:'거꾸로 생각해요.',rule:'입력과 반대로 바뀌어요',n:1,note:['입력이 꺼져 있어서 불빛은 켜져 있어요.','입력을 켜니 불빛이 꺼졌어요. 정반대죠?']},
{type:'OR',name:'하나라도',color:'#ed6c99',fg:'#352434',title:'하나만 켜도 충분해요.',rule:'A 또는 B, 하나라도 켜지면 ON',n:2,note:['A나 B, 아무 버튼이나 켜보세요.','하나라도 켜져 있으면 불빛이 켜져요.']},
{type:'AND',name:'둘 다',color:'#f5d84f',fg:'#303026',title:'둘이 함께해야 해요.',rule:'A와 B, 둘 다 켜져야 ON',n:2,note:['두 버튼을 모두 켜면 어떻게 될까요?','두 입력이 함께 켜져서 불빛이 켜졌어요.']},
{type:'XOR',name:'서로 다르게',color:'#79b975',fg:'#203622',title:'서로 다를 때 반짝!',rule:'딱 하나만 켜져야 ON',n:2,note:['둘이 같으면 꺼지고, 서로 다르면 켜져요.','딱 하나만 켜져 있어요. 그래서 불빛도 ON!']},
{type:'LATCH',name:'기억하기',color:'#303632',fg:'#f5d84f',title:'손을 떼도 기억해요.',rule:'SET은 켜기 · RESET은 끄기',n:2,note:['SET을 누르면 불빛이 켜진 상태를 기억해요.','입력이 끝나도 켜진 상태를 기억해요. RESET으로 지워보세요.']}];
let idx=0,a=false,b=false,q=false;const $=s=>document.querySelector(s);const svg=$('#circuit');
function wire(d,on){return `<path class="wire${on?' on':''}" d="${d}"/>`}
function draw(){let l=lessons[idx],v=output(l.type,a,b,q),one=l.n===1;let sy=one?[150]:[90,210];if(innerWidth<=600)sy=one?[150]:[85,215];svg.innerHTML=wire(`M50 ${sy[0]} H190 V${one?150:110} H245`,a)+(one?'':wire(`M50 ${sy[1]} H190 V190 H245`,b))+wire('M355 150 H520',v)+wire('M520 180 V240 M500 240 H540 M507 249 H533 M514 258 H526',v);
if(l.type==='WIRE')svg.innerHTML+=wire('M245 150 H355',a);else{svg.innerHTML+=`<rect class="gate" x="245" y="85" width="110" height="130" rx="${l.type==='AND'?45:16}"/><text class="gate-text" x="300" y="157" text-anchor="middle">${{NOT:'¬',OR:'≥1',AND:'&',XOR:'=1',LATCH:'Q'}[l.type]}</text>`;}
$('#lamp').classList.toggle('on',v);$('#lamp-status').textContent=v?'ON':'OFF';$('#explanation').textContent=l.note[(l.type==='NOT'?a:v)?1:0];$('#bits').textContent=l.type==='LATCH'?`Q ${+q} · MEMORY`:`A ${+a}${one?'':` / B ${+b}`} → Q ${+v}`;
for(const el of document.querySelectorAll('.input')){const val=el.dataset.key==='a'?a:b;el.classList.toggle('pressed',val);if(l.type!=='LATCH')el.setAttribute('aria-pressed',String(val));}
truth();}
function truth(){let l=lessons[idx];if(l.type==='LATCH'){$('#truth-content').innerHTML='<p>SET을 누르면 Q가 1이 되고, RESET을 누르면 0이 됩니다. 아무것도 누르지 않으면 이전 상태를 유지합니다. 이 실험은 두 명령을 차례로 받는 기억 회로입니다.</p>';return;}let rows=l.n===1?[[false,false],[true,false]]:[[false,false],[false,true],[true,false],[true,true]];$('#truth-content').innerHTML=`<table><caption>0은 꺼짐, 1은 켜짐</caption><thead><tr><th>A</th>${l.n===2?'<th>B</th>':''}<th>Q · 불빛</th></tr></thead><tbody>${rows.map(([x,y])=>`<tr class="${a===x&&(l.n===1||b===y)?'active-row':''}"><td>${+x}</td>${l.n===2?`<td>${+y}</td>`:''}<td>${+output(l.type,x,y)}</td></tr>`).join('')}</tbody></table>`;}
function select(i){idx=i;a=b=q=false;let l=lessons[idx];document.documentElement.style.setProperty('--board',l.color);document.documentElement.style.setProperty('--fg',l.fg);document.documentElement.style.setProperty('--line',l.type==='LATCH'?'#f5e8be':'#28332c');document.querySelector('meta[name="theme-color"]').content=l.color;$('#gate-title').textContent=l.type;$('#subtitle').textContent=l.title;$('#rule').textContent=l.rule;$('#chapter').textContent=`0${i+1} / 06`;$('#lesson-label').textContent=`0${i+1} · ${l.name}`;$('#next').innerHTML=i===5?'처음 회로 <span>↗</span>':'다음 회로 <span>↗</span>';$('#inputs').innerHTML=Array.from({length:l.n},(_,n)=>{let key=n?'b':'a',label=l.type==='LATCH'?(n?'RESET':'SET'):key.toUpperCase();return `<div class="input-wrap" style="top:${l.n===1?50:n?70:30}%"><button class="input ${n?'red':''}" data-key="${key}" aria-label="${label}${l.type==='LATCH'?'':' 입력 전환'}" ${l.type==='LATCH'?'':'aria-pressed="false"'}>${l.type==='LATCH'?(n?'−':'+'):label}</button><span class="input-caption">${l.type==='LATCH'?label:'INPUT '+label}</span></div>`}).join('');document.querySelectorAll('.input').forEach(el=>el.onclick=()=>{if(l.type==='LATCH'){q=latch(q,el.dataset.key==='a'?'set':'reset');}else if(el.dataset.key==='a')a=!a;else b=!b;draw();});document.querySelectorAll('.chapter').forEach((el,n)=>el.setAttribute('aria-current',String(n===i)));draw();}
$('.chapters').innerHTML=lessons.map((l,i)=>`<button class="chapter" data-i="${i}" aria-current="false"><span class="swatch" style="background:${l.color}"></span><strong>${l.type}</strong><small>${l.name}</small></button>`).join('');document.querySelectorAll('.chapter').forEach(el=>el.onclick=()=>select(+el.dataset.i));$('#next').onclick=()=>select((idx+1)%6);$('#reset').onclick=()=>select(idx);$('.brand').onclick=e=>{e.preventDefault();select(0);};$('#help').onclick=()=>{let expanded=$('#help').getAttribute('aria-expanded')==='true';$('#help').setAttribute('aria-expanded',String(!expanded));$('#guide').hidden=expanded;};window.addEventListener('resize',draw);select(0);
